# Generated by the Niobium FHE Application Design AI Assistant (FHEanna).
#
# Plaintext reference: Framingham 2008 office-based (BMI, non-laboratory)
# 10-year general cardiovascular disease risk.
#
#   D'Agostino RB Sr, Vasan RS, Pencina MJ, et al. "General cardiovascular risk
#   profile for use in primary care: the Framingham Heart Study."
#   Circulation 2008;117(6):743-753. doi:10.1161/CIRCULATIONAHA.107.699579
#
# Coefficients as published (non-laboratory model) and as carried by the
# CVrisk R package v1.2.1 (`frs_simple_coef`, function `ascvd_10y_frs_simple`):
# https://github.com/vcastro/CVrisk
#
# This is the ground truth every later version (twin, encrypted program) is
# measured against. Standard library only.

import math
import random

COEF = {
    "male": {
        "ln_age": 3.11296,
        "ln_bmi": 0.79277,
        "ln_untreated_sbp": 1.85508,
        "ln_treated_sbp": 1.92672,
        "smoker": 0.70953,
        "diabetes": 0.53160,
        "group_mean": 23.9388,
        "baseline_survival": 0.88431,
    },
    "female": {
        "ln_age": 2.72107,
        "ln_bmi": 0.51125,
        "ln_untreated_sbp": 2.81291,
        "ln_treated_sbp": 2.88267,
        "smoker": 0.61868,
        "diabetes": 0.77763,
        "group_mean": 26.0145,
        "baseline_survival": 0.94833,
    },
}

# Input contract the client enforces before encrypting (inclusive).
# Age is the model's validity range (CVrisk returns NA outside it); BMI and
# systolic blood pressure are plausible clinical ranges chosen for this example.
BOUNDS = {
    "age": (30.0, 74.0),
    "bmi": (15.0, 50.0),
    "sbp": (90.0, 200.0),
}


# CVrisk tests/testthat/test-ascvd_10y_frs_simple.R, "55yo male example":
# male, 55, BMI 30, SBP 140 untreated, non-smoker, non-diabetic -> 16.75 %.
CVRISK_CASE = ("male", 55.0, 30.0, 140.0, 0, 0, 0)
CVRISK_EXPECTED = 16.75


def linear_predictor(sex, age, bmi, sbp, bp_treated, smoker, diabetic):
    """Sum of coefficient * transformed input (the Cox linear predictor)."""
    c = COEF[sex]
    lp = c["ln_age"] * math.log(age) + c["ln_bmi"] * math.log(bmi)
    lp += (c["ln_treated_sbp"] if bp_treated else c["ln_untreated_sbp"]) * math.log(sbp)
    lp += c["smoker"] * smoker + c["diabetes"] * diabetic
    return lp


def risk(sex, age, bmi, sbp, bp_treated, smoker, diabetic):
    """10-year risk as a fraction in [0, 1] (unclamped, as published)."""
    c = COEF[sex]
    lp = linear_predictor(sex, age, bmi, sbp, bp_treated, smoker, diabetic)
    return 1.0 - c["baseline_survival"] ** math.exp(lp - c["group_mean"])


def cvrisk_display(r):
    """CVrisk's reported value: percent, clamped to [1, 30], 2 decimals."""
    return round(min(max(r * 100.0, 1.0), 30.0), 2)


def category(r):
    """Conventional 10-year risk bands: low <10%, intermediate 10-20%, high >=20%."""
    p = r * 100.0
    return "low" if p < 10.0 else ("intermediate" if p < 20.0 else "high")


def in_bounds(age, bmi, sbp):
    v = {"age": age, "bmi": bmi, "sbp": sbp}
    return all(BOUNDS[k][0] <= v[k] <= BOUNDS[k][1] for k in BOUNDS)


def test_patients(n=5000, seed=2026):
    """Synthetic representative patients plus every corner of the input box.

    Random part: roughly adult-primary-care-shaped distributions (not fitted
    to any cohort). Corner part: every combination of the bound extremes and
    the yes/no inputs, so the extremes of the scored range are always tested.
    """
    rng = random.Random(seed)
    pts = [CVRISK_CASE]  # row 0: the published test case, the default single-patient run
    for _ in range(n):
        sex = rng.choice(["male", "female"])
        age = rng.uniform(*BOUNDS["age"])
        bmi = min(max(rng.lognormvariate(math.log(27.0), 0.18), BOUNDS["bmi"][0]), BOUNDS["bmi"][1])
        sbp = min(max(rng.gauss(128.0, 18.0), BOUNDS["sbp"][0]), BOUNDS["sbp"][1])
        pts.append((sex, round(age, 1), round(bmi, 1), round(sbp),
                    int(rng.random() < 0.25), int(rng.random() < 0.18), int(rng.random() < 0.10)))
    for sex in ("male", "female"):
        for age in BOUNDS["age"]:
            for bmi in BOUNDS["bmi"]:
                for sbp in BOUNDS["sbp"]:
                    for t in (0, 1):
                        for s in (0, 1):
                            for d in (0, 1):
                                pts.append((sex, age, bmi, sbp, t, s, d))
    return pts


def _oracle_check():
    got = cvrisk_display(risk(*CVRISK_CASE))
    assert got == CVRISK_EXPECTED, got
    return got


if __name__ == "__main__":
    print("CVrisk oracle vector (male 55, BMI 30, SBP 140 untreated):",
          _oracle_check(), "% (expected 16.75)")
    pts = test_patients()
    rs = [risk(*p) for p in pts]
    cats = [category(r) for r in rs]
    print(f"{len(pts)} test patients; risk range {min(rs)*100:.3f}% .. {max(rs)*100:.2f}%")
    for c in ("low", "intermediate", "high"):
        print(f"  {c:12s} {cats.count(c):5d}")
